cd /Users/adam/Developer/vcs3/github.vexyart/vexy-hrefc-js
echo "=== BUILD ==="; npm run build 2>&1 | grep -E 'built|KB'
echo "=== TEST ==="; node --test 2>&1 | grep -E 'tests [0-9]+|pass [0-9]+|fail [0-9]+' | tail -3
echo "=== HEADLESS DOM VERIFY ==="
cat > scratch-verify.mjs << 'EOF'
import { parseHTML, DOMParser } from 'linkedom';
const { window, document } = parseHTML('<!doctype html><html><head><style id="pagecss"></style></head><body><a class="hrefc" href="https://example.com/page">link</a></body></html>');
Object.assign(globalThis, { window, document, Element: window.Element, Node: window.Node, HTMLElement: window.HTMLElement, DOMParser });
globalThis.location = { href: 'https://host.test/', origin: 'https://host.test' };
window.location = globalThis.location;
globalThis.requestAnimationFrame = (cb) => setTimeout(cb, 0);
globalThis.fetch = async () => ({ ok: true, status: 200, url: 'https://target.test/', text: async () => '<html><head><meta property="og:title" content="Image Overview | Vexy Lines Help"><meta property="og:description" content="A source image is the bitmap a Vexy Lines document is built on."></head><body></body></html>' });
window.Element.prototype.getBoundingClientRect = () => ({ top: 300, left: 80, bottom: 320, right: 180, width: 100, height: 20 });
Object.defineProperty(document.documentElement, 'clientWidth', { value: 1024, configurable: true });
Object.defineProperty(document.documentElement, 'clientHeight', { value: 768, configurable: true });

const { hrefc } = await import('./src/index.js');
const inst = hrefc({
  trigger: 'manual',
  content: { stripTitleSuffix: true, titleSeparators: ['|'], cta: 'Click to read more' },
  fetch: { proxies: [async () => '<html><head><meta property="og:title" content="Image Overview | Vexy Lines Help"><meta property="og:description" content="A source image is the bitmap."></head><body></body></html>'] },
});
await inst.show(document.querySelector('a.hrefc'));
await new Promise((r) => setTimeout(r, 40));

const popup = document.querySelector('.hrefc-popup');
const card = document.querySelector('.hrefc-card');
const arrow = document.querySelector('.hrefc-arrow');
const title = document.querySelector('.hrefc-title');
const cta = document.querySelector('.hrefc-cta');
const styleEl = document.querySelector('style[data-hrefc-styles]');
console.log('popup shown:        ', popup?.getAttribute('data-show'));
console.log('data-placement:     ', popup?.getAttribute('data-placement'), '(want top — above the link)');
console.log('card present:       ', !!card);
console.log('arrow present:      ', !!arrow, '| arrow.left set:', !!arrow?.style.left, arrow?.style.left);
console.log('title (trimmed):    ', JSON.stringify(title?.textContent));
console.log('cta text:           ', JSON.stringify(cta?.textContent));
console.log('styles prepended:   ', document.head.firstChild === styleEl, '(want true — page CSS wins)');
EOF
node scratch-verify.mjs 2>&1 | tail -12
rm -f scratch-verify.mjs
